#requires -Version 5.1
param([ValidateSet('install','remove')][string]$Action,[Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$Data)
$ErrorActionPreference='Stop'
# Sunlogin backend service integration. Installs through the vendor's silent
# service-only installer anchored at this version directory and journals the
# registered services; remove deletes exactly the recorded, root-anchored ones.
$Root=[IO.Path]::GetFullPath($Root).TrimEnd('\')
$outer=Join-Path $Root 'AweSun.exe'
$journal=Join-Path $Data 'piko-sunlogin-service.json'
if(!(Test-Path -LiteralPath $outer -PathType Leaf)){throw 'Outer AweSun.exe missing from this version directory'}
function Get-ImagePath([string]$PathName){
 $p=$PathName.Trim()
 if($p.StartsWith('"')){
  $end=$p.IndexOf('"',1)
  if($end -gt 1){$p=$p.Substring(1,$end-1)}else{$p=$p.Substring(1)}
 }
 $p
}
function Test-UnderRoot([string]$PathName){(Get-ImagePath $PathName).StartsWith($Root,[System.StringComparison]::OrdinalIgnoreCase)}
function Get-RootServices{@(Get-CimInstance Win32_Service|Where-Object{$_.PathName -and (Test-UnderRoot $_.PathName)})}
$record=$null
if(Test-Path -LiteralPath $journal){
 $record=Get-Content -LiteralPath $journal -Raw|ConvertFrom-Json
 if($record.schemaVersion -ne 1){throw 'Unsupported service ownership receipt'}
 if($record.root -ine $Root){throw 'Another Piko version owns the Sunlogin service registration; remove that version first'}
}
if($Action -eq 'install'){
 if($record -and $record.state -eq 'installed' -and (Get-RootServices).Count){throw 'Service integration already installed for this version'}
 foreach($foreign in @(Get-CimInstance Win32_Service -Filter "Name='AweSunService' OR Name='SunloginService'")){
  if($foreign.PathName -and !(Test-UnderRoot $foreign.PathName)){throw ('Existing external Sunlogin service '+$foreign.Name+' points outside this version ('+$foreign.PathName+'); remove it through its owner first')}
 }
 $null=[IO.Directory]::CreateDirectory($Data)
 @{schemaVersion=1;root=$Root;state='installing';started=(Get-Date).ToUniversalTime().ToString('o')}|ConvertTo-Json|Set-Content -LiteralPath $journal -Encoding UTF8
 $proc=Start-Process -FilePath $outer -ArgumentList @('--mod=install','--admin=1','--cmd=install_silent','--serviceonly=1',('--path="'+$Root+'"')) -PassThru
 $deadline=(Get-Date).AddSeconds(180)
 $ok=$false
 do{
  Start-Sleep -Seconds 3
  $service=Get-CimInstance Win32_Service -Filter "Name='AweSunService'"
  if($service -and $service.State -eq 'Running' -and (Test-UnderRoot $service.PathName)){$ok=$true;break}
  if($proc.HasExited -and $proc.ExitCode -ne 0){throw ('Vendor service installer failed with exit code '+$proc.ExitCode)}
 }while((Get-Date) -lt $deadline)
 if(!$ok){throw 'Vendor service installer did not reach a running AweSunService under this version directory'}
 if(!$proc.HasExited -and !$proc.WaitForExit(15000)){Stop-Process -Id $proc.Id -Force}
 $names=@(Get-RootServices|ForEach-Object{$_.Name})
 @{schemaVersion=1;root=$Root;state='installed';services=$names;outer=(Get-Item -LiteralPath $outer).VersionInfo.FileVersion.ToString();installed=(Get-Date).ToUniversalTime().ToString('o')}|ConvertTo-Json|Set-Content -LiteralPath $journal -Encoding UTF8
 Write-Output ('Installed Sunlogin service registration: '+($names -join ', '))
}else{
 if(!$record -or $record.state -ne 'installed'){throw 'No owned Sunlogin service registration for this version'}
 $names=@((Get-RootServices|ForEach-Object{$_.Name})+@($record.services|Where-Object{$_})|Where-Object{$_}|Select-Object -Unique)
 foreach($name in $names){
  $svc=Get-CimInstance Win32_Service -Filter ("Name='"+$name+"'")
  if(!$svc){continue}
  if(!(Test-UnderRoot $svc.PathName)){Write-Output ('Skipped externally-owned service: '+$name);continue}
  $null=sc.exe stop $name
  if($svc.ProcessId){Stop-Process -Id $svc.ProcessId -Force -ErrorAction SilentlyContinue}
  $null=sc.exe delete $name
  if(Get-CimInstance Win32_Service -Filter ("Name='"+$name+"'")){throw ('Failed to delete service: '+$name)}
 }
 Remove-Item -LiteralPath $journal
 Write-Output 'Removed Sunlogin service registration for this version'
}
